import os
import pandas as pd
import numpy as np
import re

PRED_FILE = "pred_results/pred_illuminate.csv"

ALLOWED_ELEMENTS = {'C', 'N', 'O', 'S', 'P', 'F', 'Cl', 'Br', 'I'}
MIN_HEAVY = 5
MAX_HEAVY = 50

# Thresholds - relaxed to be fair
ARCHIVE_SIZE_THRESHOLD = 100  # At least 100 molecules
MEAN_QED_THRESHOLD = 0.50     # Mean QED should be reasonable
GLOBAL_MAX_QED_THRESHOLD = 0.70  # At least one good molecule
VALIDITY_RATE_THRESHOLD = 0.70   # 70% valid molecules


def try_import_rdkit():
    """Try to import rdkit, return None if unavailable."""
    try:
        from rdkit import Chem
        from rdkit.Chem import QED as rdkitQED
        return Chem, rdkitQED
    except Exception:
        return None, None


def basic_smiles_check(smi):
    """Basic SMILES validation without RDKit - check it's a non-empty string."""
    if not isinstance(smi, str) or len(smi.strip()) == 0:
        return False
    # Basic sanity: contains at least one letter (atom symbol)
    if not re.search(r'[A-Za-z]', smi):
        return False
    return True


def find_column(df, possible_names, required=True):
    """Find a column by trying multiple possible names (case-insensitive)."""
    col_lower = {col.lower(): col for col in df.columns}
    for name in possible_names:
        if name.lower() in col_lower:
            return col_lower[name.lower()]
    if required:
        return None
    return None


def eval():
    # 1. Check file existence
    if not os.path.exists(PRED_FILE):
        return (False, f"Predicted output file '{PRED_FILE}' not found.")

    # 2. Load and validate format
    try:
        pred_df = pd.read_csv(PRED_FILE)
    except Exception as <local-path>        return (False, f"Failed to read predicted CSV: {e}")

    if len(pred_df) == 0:
        return (False, "Predicted output file is empty.")

    # 3. Find SMILES column (flexible naming)
    smiles_col = find_column(pred_df, ['smiles', 'smi', 'molecule', 'mol_smiles'])
    if smiles_col is None:
        return (False, f"No SMILES column found. Available columns: {list(pred_df.columns)}")

    # 4. Find fitness/QED column (flexible naming)
    fitness_col = find_column(pred_df, ['fitness', 'qed', 'score', 'objective', 'reward'])
    if fitness_col is None:
        return (False, f"No fitness/QED column found. Available columns: {list(pred_df.columns)}")

    # 5. Find niche column (optional but preferred)
    niche_col = find_column(pred_df, ['niche', 'niche_index', 'niche_idx', 'cell'], required=False)

    # 6. Find generation column (optional)
    gen_col = find_column(pred_df, ['generation', 'gen', 'iteration'], required=False)

    print(f"Using columns: SMILES='{smiles_col}', Fitness='{fitness_col}', "
          f"Niche='{niche_col}', Generation='{gen_col}'")

    # 7. Validate SMILES and compute validity rate
    Chem, rdkitQED = try_import_rdkit()

    valid_count = 0
    total = len(pred_df)
    fitness_values = []
    computed_qed_values = []
    canonical_smiles_set = set()

    for idx, row in pred_df.iterrows():
        smi = str(row[smiles_col])
        fit_val = float(row[fitness_col]) if pd.notna(row[fitness_col]) else 0.0
        fitness_values.append(fit_val)

        if Chem is not None:
            mol = Chem.MolFromSmiles(smi)
            if mol is not None:
                n_heavy = mol.GetNumHeavyAtoms()
                if MIN_HEAVY <= n_heavy <= MAX_HEAVY:
                    element_valid = True
                    for atom in mol.GetAtoms():
                        if atom.GetSymbol() not in ALLOWED_ELEMENTS:
                            element_valid = False
                            break
                    if element_valid:
                        valid_count += 1
                        canonical_smiles_set.add(Chem.MolToSmiles(mol))
                        if rdkitQED is not None:
                            try:
                                computed_qed_values.append(rdkitQED.qed(mol))
                            except Exception:
                                pass
        else:
            # Fallback: basic string check
            if basic_smiles_check(smi):
                valid_count += 1
                canonical_smiles_set.add(smi.strip())

    fitness_values = np.array(fitness_values)
    validity_rate = valid_count / total if total > 0 else 0.0

    # 8. Check fitness value range (should be between 0 and 1 for QED)
    fitness_in_range = np.all((fitness_values >= 0) & (fitness_values <= 1))

    # 9. Compute quality metrics
    archive_size = len(canonical_smiles_set) if canonical_smiles_set else total

    # Use fitness values as QED proxy if RDKit unavailable
    mean_qed = float(fitness_values.mean()) if len(fitness_values) > 0 else 0.0
    global_max_qed = float(fitness_values.max()) if len(fitness_values) > 0 else 0.0

    # If we have RDKit-computed QED, verify fitness values are reasonable
    fitness_mismatch_count = 0
    if computed_qed_values and len(computed_qed_values) > 10:
        # Check correlation between reported fitness and computed QED
        # Use a lenient approach: check if values are in similar range
        computed_mean = np.mean(computed_qed_values)
        reported_mean = np.mean(fitness_values[:len(computed_qed_values)])
        if abs(computed_mean - reported_mean) > 0.3:
            fitness_mismatch_count = len(computed_qed_values)

    # 10. Check niche diversity if niche column exists
    if niche_col is not None:
        unique_niches = pred_df[niche_col].nunique()
        coverage = unique_niches / 1000.0
    else:
        # Estimate diversity from archive size
        unique_niches = archive_size
        coverage = min(archive_size / 150.0, 1.0)  # Normalized coverage estimate

    # 11. Check generation info if available
    has_generation_info = gen_col is not None

    # 12. Build result summary
    reasons = []

    if validity_rate < VALIDITY_RATE_THRESHOLD:
        reasons.append(
            f"Structural validity rate {validity_rate:.1%} < {VALIDITY_RATE_THRESHOLD:.0%}"
        )

    if archive_size < ARCHIVE_SIZE_THRESHOLD:
        reasons.append(f"Archive size {archive_size} < {ARCHIVE_SIZE_THRESHOLD}")

    if global_max_qed < GLOBAL_MAX_QED_THRESHOLD:
        reasons.append(
            f"Global Max QED/Fitness {global_max_qed:.4f} < {GLOBAL_MAX_QED_THRESHOLD}"
        )

    if mean_qed < MEAN_QED_THRESHOLD:
        reasons.append(
            f"Mean QED/Fitness {mean_qed:.4f} < {MEAN_QED_THRESHOLD}"
        )

    if not fitness_in_range:
        # Check if values might be on different scale
        if global_max_qed > 1.0 or global_max_qed < 0.0:
            reasons.append(
                f"Fitness values out of expected [0,1] range for QED: "
                f"min={fitness_values.min():.4f}, max={fitness_values.max():.4f}"
            )

    if fitness_mismatch_count > 0 and len(computed_qed_values) > 10:
        reasons.append(
            f"Fitness values appear inconsistent with computed QED "
            f"(mean diff > 0.3): reported={np.mean(fitness_values[:len(computed_qed_values)]):.4f}, "
            f"computed={np.mean(computed_qed_values):.4f}"
        )

    summary = (
        f"ArchiveSize={archive_size}, ValidityRate={validity_rate:.1%}, "
        f"MeanQED={mean_qed:.4f}, GlobalMaxQED={global_max_qed:.4f}, "
        f"UniqueNiches={unique_niches}, HasGenerationInfo={has_generation_info}, "
        f"Columns={list(pred_df.columns)}"
    )

    if reasons:
        return (False, f"FAILED: {'; '.join(reasons)}. Details: {summary}")
    else:
        return (True, f"PASSED: All metrics within thresholds. {summary}")


if __name__ == "__main__":
    passed, reason = eval()
    print(f"Result: {'PASS' if passed else 'FAIL'}")
    print(f"Reason: {reason}")

